import sys

def main():
    s = sys.stdin.read().split()[0]
    cnt = {}
    first = {}
    for i, c in enumerate(s):
        cnt[c] = cnt.get(c, 0) + 1
        if c not in first:
            first[c] = i
    best = max(cnt, key=lambda c: (cnt[c], -first[c]))
    print(best, cnt[best])

main()

